59	// Helper to identify if a tool should use the compact view
60	export const isCompactTool = (
61	  tool: IndividualToolCallDisplay,
62	  isCompactModeEnabled: boolean,
63	): boolean => {
64	  const hasCompactOutputSupport = COMPACT_OUTPUT_ALLOWLIST.has(tool.name);
65	  const displayStatus = mapCoreStatusToDisplayStatus(tool.status);
66	  return (
67	    isCompactModeEnabled &&
68	    hasCompactOutputSupport &&
69	    displayStatus !== ToolCallStatus.Confirming
70	  );
71	};
