73	// Helper to identify if a compact tool has a payload (diff, list, etc.)
74	export const hasDensePayload = (tool: IndividualToolCallDisplay): boolean => {
75	  if (tool.outputFile) return true;
76	  const res = tool.resultDisplay;
77	  if (!res) return false;
78	
79	  // TODO(24053): Usage of type guards makes this class too aware of internals
80	  if (isFileDiff(res)) return true;
81	  if (tool.confirmationDetails?.type === 'edit') return true;
82	
83	  // Generic summary/payload pattern
84	  if (
85	    typeof res === 'object' &&
86	    res !== null &&
87	    'summary' in res &&
88	    'payload' in res
89	  ) {
90	    return true;
91	  }
92	
93	  return false;
94	};
